    "description": "The Business Analytics Manager identifies and translates market opportunities into actionable recommendations for the organization. They supervise professionals in gathering and analyzing business intelligence (BI) data to help make informed business decisions. They manage the timely reporting of data analysis outcomes and effectively cmmunicate findings, insights and o recommendations to business leaders. They develop data and/or information quality metrics and research new technology and develop business cases to support enterprise-wide business intelligence solutions. They are responsible for developing guidelines on data insight reporting for the team. They are also responsible for managing BI-related projects from end to end. They manage a team and are proficient in the analytics tools and technique s required by the organization. They are also familiar with the relevant software platforms on which the solution is deployed on. The Business Analytics Manager has a deep passion for analyzing and resolving complex problems through a systematic approach. They display an intellectual curiosity as well as the capability to engage with stakeholders to understand business issues.",
