        "description": "The Data Governance Manager executes data governance policies and procedures. They ensure that relevant data protection regulations are implemented and enforced in the organization, and amongst the respective teams and users. They collaborate with business and project teams in projects and ensure alignment and compliance with the organization's data protection guidelines and policies, and with industry standards and guidelines. They also direct a team of professionals and third-party vendors or service providers to achieve organizational goals in accordance with the data governance and data protection policies. They manage risks and data breach incidents. The Data Governance Manager is knowledgeable in areas of data governance, compliance, and data protection policies and frameworks, and works within and across teams to mitigate data breaches. They are expected to be proficient in the requirements of vari ous relevant global regulations on data protection. The Data Governance Manager adopts a broad and global perspective in their work, and is confident in making critical decisions and handl ng competing resource needs that i may have implications on various projects and stakeholders.",
