    "id": "data-engineer",
    "title": "Data Engineer",
    "description": "The Data Engineer supports the design, implementation and maintenance of data flow channels and data processing systems that support the collection, storage, batch and real-time processing, and analysis of information in a scalable, repeatable and secu re manner. They focus on defining optimal solutions to data collection, processing and warehousing. They design, code and test data systems and work on implementing those into the internal infrastructure. They focus on collecting, parsing, managing, analyzing and visualizing large sets of data to turn information into insights accessible through multiple platforms. They are proficient in database systems, scripting and programming languages required by the organization. They are also familiar with the relevant software platforms on which the solution is deployed on. The Data Engineer is passionate about numbers and works with large data sets. They have a keenness for understanding business processes and resolving challenges in order to provide solutions with the help of clean and interlinked databases and architectures.",
