    "description": "The Senior Data Engineer designs, implements, and oversees maintenance of data flow channels and data processing systems that support the collection, storage, batch and real-time processing, and analysis of information from structured and unstructured sources in a scalable, repeatable, and secure manner. They assist data scientists with the extraction of valuable insights from data sets to derive valuable and actionable insights and recommendations that support business requirements. They are involved in rollouts, upgrades, implementation, and release of data system changes as required for streamlining of internal practices. They are proficient in database systems, scripting, and programming languages required by the organization. They are also familiar with the relevant software platforms on which the solution is deployed on. The Senior Data Engineer possesses a natural inclination for understanding business processes and relevant data requirements. They easily build rapport with others and are able to put forth their ideas and recommendations in a persuasive manner, to influence stakeholders a nd decisions.",
