    "id": "machine-learning-engineer",
    "title": "Machine Learning Engineer",
    "description": "The Machine Learning Engineer supports the production of scalable and optimized machine learning (ML) models. They focus on building algorithms for the extraction, transformation and loading of large volumes of real-time, unstructured data in order to deploy ML solutions from theoretical data science models. They run experiments to test the performance of deployed models, and identify and resolve bugs that arise in the process. They work in a team sett ing and are proficient in statistics, scripting and programming languages required by the organization. They are also familiar with the relevant software platforms in which the models are deployed. They should be knowledgeable of the requirements of data governance frameworks and data protection regulations in the course of their work on ML models. The Machine Learning Engineer is a determi ned individual who is comfortable working with large data sets, has a keen interest in problem solving and experimentation, and enjoys the iterative process of development and resolving issues.",
