    "id": "ai-engineer",
    "title": "AI Engineer",
    "description": "The AI Engineer specializes in the development and application of artificial intelligence technologies. This role is focused on leading the creation of new and advanced AI methodologies and analytical solutions, including architecting specialized database and computing environments tailored for AI applications. The AI Engineer is responsible for identifying and developing key AI components essential for the delivery of projects, conducting rigorous testing on AI models, interpreting results, and assessing model performance for practical deployment. An important aspect of this role is the ability to develop communication materials that effectively facilitate stakeholder buy-in for AI-driven solutions. The AI Engineer must work effectively in team set tings and demonstrate proficiency in programming languages and AI-related software platforms. The AI Engineer is deeply passionate about leveraging AI to address complex business challenges and should have an innate curiosity towards AI innovations, coupled with a strong ability to influnce through effective communication e and data storytelling.",
