        "description": "The Associate Data Engineer blends historical data from available industry reports, public information, field reports or purchased sources, basic data cleaning and tr ansformation, and performs analysis to support business and product decisions. They use development tools to generate reports, dashboards, clean and prepare the data and analytical solutions according to business rules and specifications. They are a part of important projects and coordinate with internal teams to develop projections on outcomes of implementing business strategies that result in actionable insights. They also assist in the data collection, processing and warehousing tasks, which may also include collection, parsing, analyzing and visualizing large sets of data. They work in a team setting and are proficient in the analytics tools and techniques required by the organization. They are also familiar with the relevant software platforms on which the solution is deployed on. The Associate Data Engineer is meticulous and detailed-oriented. They enjoy working with data and displays willingness to learn. They adopt an analytical approach to solving problems and display confidence when communicating ideas.",
