    "id": "director-of-research",
    "title": "Director of Research",
    "description": "The Director of Research leads the organization's research strategy in AI and data analytics. This role involves setting long-term research goals, securing funding, overseeing major projects, and maintaining relationships with academic and industry partners. The Director of Research ensures that research activities align with the organization's vision and market trends. They are responsible for building and maintaining a high-performing research team and fostering a culture of innovation. The position requires extensive experience in data analytics and AI research, strategic planning skills, and the ability to drive research initiatives th at have a significant impact on the organization.",
